<?php require __DIR__.'/bootstrap.php';messenger_run(function($u){$in=messenger_input();$id=(int)($in['id']??0);$row=Database::fetch('SELECT * FROM chat_files WHERE id=? AND deleted_at IS NULL',[$id]);if(!$row)throw new DomainException('فایل پیدا نشد.',404);$p=MessengerSecurity::participant((int)$row['conversation_id'],(int)$u['id']);if((int)$row['uploaded_by']!==(int)$u['id']&&!in_array($p['participant_role'],['owner','admin','moderator'],true)&&!MessengerSecurity::can('messenger.moderate','delete'))throw new DomainException('حذف فایل مجاز نیست.',403);Database::execute('UPDATE chat_files SET is_deleted=1,deleted_by=?,deleted_at=NOW(),updated_at=NOW() WHERE id=?',[(int)$u['id'],$id]);MessengerService::audit((int)$u['id'],'file_deleted',(int)$row['conversation_id'],(int)($row['message_id']??0),['file_id'=>$id]);return ['deleted'=>true];},true);
